{"probes": [{"obligation_id": "OB-004", "strategy": "example", "rationale": "2023-01-02 is a Monday and 2023-01-08 is a Sunday; a 0-based or Sunday-first scheme would return 0 or 1 for Monday and 0 or 6 for Sunday instead of the required 1 and 7.", "code": "import impl


def test_weekday_monday_is_1_and_sunday_is_7():
    # 2023-01-02 is a Monday; 2023-01-08 is a Sunday (same ISO week 1 of 2023)
    monday_year, monday_week, monday_weekday = impl.to_iso_week_date(2023, 1, 2)
    sunday_year, sunday_week, sunday_weekday = impl.to_iso_week_date(2023, 1, 8)

    assert monday_weekday == 1, (
        f"Monday 2023-01-02 must have weekday=1, got {monday_weekday}"
    )
    assert sunday_weekday == 7, (
        f"Sunday 2023-01-08 must have weekday=7, got {sunday_weekday}"
    )
"}]}
